export const INLINE_PROCEDURES = {
  "niveau et couleur de l'huile moteur": '<strong>Contrôle :</strong> véhicule à plat et moteur arrêté depuis au moins 5 minutes, essuyez la jauge, réinsérez-la puis vérifiez que le niveau reste entre MIN et MAX. Une huile laiteuse, mousseuse ou contenant des particules impose un diagnostic avant utilisation.',
  'liquide de refroidissement (ldr)': '<strong>Sécurité :</strong> contrôlez uniquement moteur froid. Le niveau doit se situer entre MIN et MAX ; recherchez une pellicule huileuse, des dépôts, une couleur anormale ou des traces séchées autour du vase et des durites.',
  'fuites visibles sous le véhicule': '<strong>Contrôle :</strong> stationnez sur un sol propre, observez après plusieurs heures puis inspectez sans vous placer sous un véhicule non sécurisé. Identifiez la couleur, la texture et l’emplacement de toute trace avant de démarrer.',
  'bruits anormaux au démarrage / ralenti': '<strong>Contrôle :</strong> moteur froid puis chaud, écoutez capot ouvert sans approcher vêtements ou mains des pièces mobiles. Notez la zone, la fréquence et l’évolution du bruit avec le régime moteur.',
  "fumée à l'échappement": '<strong>Contrôle :</strong> observez la couleur uniquement à l’extérieur, moteur froid puis chaud. Une fumée bleue, noire dense ou blanche persistante accompagnée d’une baisse de niveau impose un diagnostic avant de poursuivre la route.',
  'stabilité du ralenti': '<strong>Contrôle :</strong> moteur à température et consommateurs coupés, observez le compte-tours pendant une minute. Relevez les oscillations, ratés, vibrations ou calages et vérifiez si un témoin moteur apparaît.',
  'joint de culasse (indices)': '<strong>Sécurité :</strong> n’ouvrez jamais le circuit de refroidissement à chaud. Moteur froid, recherchez une émulsion sous le bouchon d’huile, des bulles continues dans le vase, une surpression rapide ou des pertes simultanées d’huile et de liquide.',
  'supports moteur': '<strong>Contrôle :</strong> frein de stationnement serré, observez les vibrations au ralenti et les mouvements excessifs lors de la mise en charge, sans vous placer devant le véhicule. Inspectez les silentblocs à la recherche de fissures ou d’affaissement.',
  'rouille au niveau du plancher': '<strong>Contrôle :</strong> soulevez les tapis et inspectez planchers, bas de caisse et passages de roues avec une lampe. Une perforation, un métal feuilleté ou de la corrosion près d’un ancrage nécessite un contrôle professionnel.',
  "longerons & points d'ancrage": '<strong>Contrôle :</strong> recherchez plis, soudures non régulières, peinture récente, déformation et corrosion autour des longerons et ancrages. Ne passez sous le véhicule que s’il est placé sur un pont ou des chandelles homologuées.',
  'fuites pont / différentiel': '<strong>Contrôle :</strong> inspectez le carter, les joints de sortie et les zones proches des cardans. Un simple suintement doit être surveillé ; des gouttes, un niveau bas ou un grondement exigent une intervention.',
  'jeu dans les rotules / triangles': '<strong>Sécurité :</strong> faites réaliser ce contrôle sur un pont ou avec des chandelles homologuées. Recherchez soufflets déchirés, déplacement anormal et claquement ; tout jeu de direction ou suspension doit être traité avant circulation.',
  'état des amortisseurs': '<strong>Contrôle :</strong> recherchez fuite d’huile, tige endommagée, ressort cassé et différence de hauteur. Un rebond répété, une tenue de route flottante ou une fuite franche justifie un contrôle sur banc.',
  'usure des pneus (les 4)': '<strong>Contrôle :</strong> mesurez la profondeur sur plusieurs points de chaque pneu et inspectez flancs, hernies, coupures et usure intérieure. Une usure irrégulière peut révéler un défaut de pression, géométrie ou suspension.',
  'état des jantes': '<strong>Contrôle :</strong> inspectez les faces intérieure et extérieure pour détecter fissures, déformations et impacts. Une vibration, une perte de pression ou une fissure impose l’immobilisation jusqu’au contrôle.',
  'alignement des panneaux': '<strong>Contrôle :</strong> comparez les jeux entre capot, ailes, portes et coffre des deux côtés. Des écarts irréguliers, vis marquées ou différences de peinture peuvent indiquer une réparation antérieure.',
  'présence de mastic / bondo': '<strong>Contrôle :</strong> sous une lumière rasante, recherchez ondulations et différences de texture ; utilisez une jauge d’épaisseur de peinture sur plusieurs points comparables. Évitez l’aimant sur les carrosseries en aluminium ou composites.',
  'qualité et homogénéité de la peinture': '<strong>Contrôle :</strong> examinez le véhicule à la lumière naturelle sous plusieurs angles. Recherchez différences de teinte, brouillard de peinture sur joints, coulures, raccords et variations d’épaisseur.',
  'feux avant (croisement / route / clignotants)': '<strong>Contrôle :</strong> testez chaque fonction contact mis et vérifiez optiques, fixation, condensation et réglage apparent. Une optique cassée, un clignotant défaillant ou un faisceau incorrect doit être corrigé.',
  'feux arrière & stop': '<strong>Contrôle :</strong> demandez à une seconde personne d’actionner la pédale ou utilisez un reflet pour vérifier les feux stop. Testez aussi positions et clignotants, puis recherchez fissures et humidité.',
  'feux de recul & antibrouillard': '<strong>Contrôle :</strong> frein serré et véhicule immobilisé, mettez le contact et engagez la marche arrière sans démarrer si possible. Vérifiez ensuite chaque antibrouillard conformément à l’équipement du véhicule.',
  'état des sièges': '<strong>Contrôle :</strong> testez glissières, verrouillage, réglages, appuie-têtes et ceintures. Aucun siège ne doit bouger sur ses ancrages et aucun témoin d’airbag ne doit rester allumé.',
  'ciel de toit': '<strong>Contrôle :</strong> recherchez décollement, affaissement, humidité et traces autour des montants ou du toit ouvrant. Une humidité persistante nécessite la recherche de l’entrée d’eau.',
  'climatisation / chauffage': '<strong>Contrôle :</strong> testez toutes les vitesses de ventilation, les orientations et les températures. Notez les bruits, odeurs, variations de débit et l’enclenchement du compresseur lorsque le véhicule en possède un.',
  'vitres électriques (les 4)': '<strong>Contrôle :</strong> actionnez chaque vitre depuis sa commande locale et la commande conducteur. Vérifiez montée régulière, fonction antipincement et absence de bruit ou ralentissement anormal.',
  "odeurs / traces d'humidité": '<strong>Contrôle :</strong> inspectez tapis, dessous de moquette, coffre et logement de roue de secours. Odeur de moisi, buée récurrente ou isolant humide signale une infiltration à localiser.',
  "fluidité de l'accélération": '<strong>Contrôle :</strong> sur une route sûre, accélérez progressivement à plusieurs régimes sans dépasser les limitations. Notez trous, à-coups, fumée, vibrations ou témoins ; interrompez l’essai en cas de perte de puissance dangereuse.',
  'passage des vitesses': '<strong>Contrôle :</strong> moteur froid puis chaud, vérifiez chaque rapport à faible charge. Craquement, patinage, retard d’engagement ou choc marqué nécessite un diagnostic de boîte ou d’embrayage.',
  'test de braquage': '<strong>Contrôle :</strong> à très basse vitesse dans une zone dégagée, braquez progressivement des deux côtés sans maintenir longtemps la direction en butée. Recherchez claquement, point dur et différence d’assistance.',
  'freinage': '<strong>Sécurité :</strong> avant l’essai, vérifiez une pédale ferme et l’absence de témoin rouge. À faible vitesse dans une zone sûre, contrôlez efficacité, bruits et déviation ; immobilisez le véhicule si la pédale s’enfonce ou si le freinage est asymétrique.',
  'comportement à vitesse stabilisée': '<strong>Contrôle :</strong> sur une route régulière et sûre, maintenez une vitesse légale constante. Notez vibrations selon la vitesse, dérive, grondement et mouvements du volant sans relâcher son contrôle.',
  'code p1000 détecté ?': '<strong>P1000 :</strong> les moniteurs OBD ne sont pas tous terminés, souvent après effacement des défauts ou débranchement de batterie. Vérifiez l’historique et effectuez le cycle de conduite constructeur avant de conclure à l’absence de défaut.',
};

