const OBD_ACTION_PLANS = {
  timing: '1. Relever données figées et valeurs de synchronisation. 2. Contrôler niveau, pression et qualité d’huile. 3. Vérifier alimentation, faisceau et actionneur. 4. Contrôler le calage mécanique avec les outils constructeur avant remplacement.',
  air: '1. Relever données figées et comparer valeurs demandées/mesurées. 2. Contrôler alimentation, masse et signal du capteur. 3. Rechercher fuite, obstruction ou contamination du circuit. 4. Confirmer avec une mesure indépendante avant remplacement.',
  fuel: '1. Relever pression demandée/mesurée et adaptations. 2. Contrôler alimentation électrique, étanchéité et qualité du carburant. 3. Tester pompe, régulateur et injecteurs selon la procédure. 4. Ne jamais ouvrir un circuit haute pression moteur tournant.',
  ignition: '1. Relever données figées et compteurs de ratés. 2. Contrôler bougies, bobines, injecteurs et faisceaux du cylindre concerné. 3. Rechercher prises d’air. 4. Contrôler compression et étanchéité avant remplacement.',
  emissions: '1. Relever données figées et corriger d’abord les défauts moteur associés. 2. Contrôler alimentation, conduits et fuites. 3. Commander le composant et comparer les capteurs. 4. Confirmer l’efficacité avant nettoyage ou remplacement.',
  electrical: '1. Contrôler batterie, fusibles, alimentations et masses sous charge. 2. Relever données figées et défauts de tous les calculateurs. 3. Tester continuité, isolement et chute de tension du faisceau. 4. Confirmer le calculateur seulement après validation des circuits.',
  transmission: '1. Relever les codes moteur et transmission avec données figées. 2. Vérifier niveau, état et température du fluide selon la procédure. 3. Comparer vitesses, rapports, pressions et glissements. 4. Contrôler faisceau et hydraulique avant toute dépose.',
  cooling: '1. Immobiliser en cas de surchauffe réelle. 2. Contrôler niveau et fuites uniquement moteur froid. 3. Comparer température mesurée et réelle. 4. Tester thermostat, circulation, ventilateurs et pression du circuit.',
  network: '1. Tester la batterie et les alimentations de tous les modules concernés. 2. Effectuer un scan réseau complet. 3. Contrôler résistances, tensions et intégrité du bus selon le constructeur. 4. Isoler le segment fautif avant de condamner un calculateur.',
};

function createObdScenario(code, condition, possibleCauses, family = 'electrical') {
  return {
    type: 'report',
    fault_code: code,
    root_cause: `${condition}. Causes possibles : ${possibleCauses}. Le code identifie une condition détectée, pas automatiquement une pièce défectueuse.`,
    action_plan: OBD_ACTION_PLANS[family],
  };
}

